    "  WS80:[['t_out','Temp','degC',1],['h_out','Hum','%',0],['wind_dir','Dir','deg',0],['wind_spd','Wind','m/s',1],['wind_gust','Gust','m/s',1],['rain','Rain','mm',1],['rain_rate','Rate','mm/h',1],['uv','UV','UV',0],['solar','Solar','W/m2',0]],\n"
    "  WS68:[['t_out','Temp','degC',1],['h_out','Hum','%',0],['wind_dir','Dir','deg',0],['wind_spd','Wind','m/s',1],['wind_gust','Gust','m/s',1],['rain','Rain','mm',1],['rain_rate','Rate','mm/h',1],['uv','UV','UV',0],['solar','Solar','W/m2',0]],\n"
    "  WS85:[['t_out','Temp','degC',1],['h_out','Hum','%',0],['wind_dir','Dir','deg',0],['wind_spd','Wind','m/s',1],['wind_gust','Gust','m/s',1],['rain','Rain','mm',1],['rain_rate','Rate','mm/h',1],['uv','UV','UV',0],['solar','Solar','W/m2',0]],\n"
    "  WH24:[['t_out','Temp','degC',1],['h_out','Hum','%',0],['wind_dir','Dir','deg',0],['wind_spd','Wind','m/s',1],['wind_gust','Gust','m/s',1],['rain','Rain','mm',1],['rain_rate','Rate','mm/h',1],['uv','UV','UV',0],['solar','Solar','W/m2',0]],\n"
    "  WH65:[['t_out','Temp','degC',1],['h_out','Hum','%',0],['wind_dir','Dir','deg',0],['wind_spd','Wind','m/s',1],['wind_gust','Gust','m/s',1],['rain','Rain','mm',1],['rain_rate','Rate','mm/h',1],['uv','UV','UV',0],['solar','Solar','W/m2',0]],\n"
    "  WS69:[['t_out','Temp','degC',1],['h_out','Hum','%',0],['wind_dir','Dir','deg',0],['wind_spd','Wind','m/s',1],['wind_gust','Gust','m/s',1],['rain','Rain','mm',1],['rain_rate','Rate','mm/h',1],['uv','UV','UV',0],['solar','Solar','W/m2',0]],\n"
    "  WH31:[['t_out','Temp','degC',1],['h_out','Hum','%',0]],\n"
    "  WH51:[['soil_moist','Moist','%',0]],\n"
    "  WH52:[['soil_moist','Moist','%',0],['soil_t','Temp','degC',1],['soil_ec','EC','uS/cm',0]],\n"
    "  WN34:[['soil_t','Temp','degC',1]],\n"
    "  WN38:[['soil_t','Temp','degC',1]],\n"
    "  WH40:[['rain','Rain','mm',1]],\n"
    "  WN20:[['rain','Rain','mm',1]],\n"
    "  WH41:[['pm25','PM2.5','ug/m3',1],['pm10','PM10','ug/m3',0]],\n"
    "  WH43:[['pm25','PM2.5','ug/m3',1]],\n"
    "  WH45:[['pm25','PM2.5','ug/m3',1],['co2','CO2','ppm',0]],\n"
    "  WH46:[['pm25','PM2.5','ug/m3',1],['co2','CO2','ppm',0]],\n"
    "  WH57:[['light_cnt','Strikes','',0],['light_dist','Dist','km',0]],\n"
    "  WH55:[['leak','Leak','',0]]\n"
    "};\n"
    "function cardinal(d){return ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'][Math.round(d/22.5)%16];}\n"
    "function editing(){const a=document.activeElement;return a&&(a.tagName==='INPUT'||a.tagName==='SELECT'||a.tagName==='TEXTAREA');}\n"
    "function miniVal(src,key,label,unit,dec){\n"
    "  const v=src[key];\n"
    "  if(v==null||v==='')return '';\n"
    "  const n=Number(v);\n"
    "  const lab='<span class=\"mk\">'+label+'</span>';\n"
    "  if(key==='leak')return '<span class=\"mv'+(n\?' crit':' zero')+'\">'+lab+(n\?'LEAK':'DRY')+'</span>';\n"
    "  if(key==='rain_state')return '<span class=\"mv'+(n\?' crit':' zero')+'\">'+lab+(n\?'RAIN':'DRY')+'</span>';\n"
    "  if(key==='wind_dir'||key==='wind_avg')return '<span class=\"mv\">'+lab+cardinal(n)+' '+fmt(v,dec)+'<i class=\"mu\">deg</i></span>';\n"
    "  return '<span class=\"mv'+(n===0\?' zero':'')+'\">'+lab+fmt(v,dec)+'<i class=\"mu\">'+unit+'</i></span>';\n"
    "}\n"
    "function sensorCard(s){\n"
    "  const reads=FAM_READS[s.fam]||[];\n"
    "  const v=s.v||{};\n"
    "  const vals=reads.map(r=>miniVal(v,r[0],r[1],r[2],r[3])).filter(Boolean);\n"
    "  if(s.fam==='Indoor'){  // built-in I2C sensor: no id/rssi/batt meta\n"
    "    return '<div class=\"scard\"><div class=\"sh\"><div><div class=\"sn\">Indoor</div></div></div>'+\n"
    "      (vals.length\?'<div class=\"sreads\">'+vals.join('')+'</div>':'')+'</div>';\n"
    "  }\n"
    "  const l=rssiLevel(s.rssi), sc=l>=4\?'good':(l===3\?'warn':(l===2\?'ser':'crit'));\n"
    "  const a=age(s.last);\n"
    "  return '<div class=\"scard\"><div class=\"sh\">'+\n"
    "    '<div><div class=\"sn\">'+esc(s.fam)+'</div><div class=\"sid mono\">'+esc(s.id||'')+'</div></div>'+\n"
    "    '<div class=\"smeta\">'+\n"
    "      '<span class=\"sbatt '+(s.batt\?'warn':'ok')+'\">'+(s.batt\?'LOW':'OK')+'</span>'+\n"
    "      '<span class=\"mono rssi\">'+seg(l,sc)+s.rssi+' dBm</span>'+\n"
    "      '<span class=\"mono muted\">'+a+'</span>'+\n"
    "    '</div></div>'+\n"
    "    (vals.length\?'<div class=\"sreads\">'+vals.join('')+'</div>':'')+\n"
    "    '</div>';\n"
    "}\n"
    "function renderLive(){\n"
    "  const dev=S.dev||{};\n"
    "  $('liveDev').innerHTML=\n"
    "    '<span class=\"nm\">'+esc(dev.name||'GW1100')+'</span>'+\n"
    "    '<span class=\"muted\">'+esc(dev.fw||'')+'</span>'+\n"
    "    '<span class=\"mono\">'+esc(dev.ip||'\?\?\?')+' \?\? '+esc(dev.mac||'\?\?\?')+'</span>'+\n"
    "    '<span class=\"mono\">'+esc(dev.ssid||'\?\?\?')+(dev.wifi_rssi!=null\?' '+dev.wifi_rssi+' dBm':'')+'</span>'+\n"
    "    '<span class=\"mono\">'+fmtUpt(dev.uptime)+' up</span>'+\n"
    "    '<span class=\"mono\">'+fmtKB(dev.heap)+' free</span>';\n"
    "  const ro=(S.roster||[]).filter(s=>s.en!==false);\n"
    "  $('liveGrid').innerHTML=ro.length\?'<div class=\"scards\">'+ro.map(sensorCard).join('')+'</div>':'<div class=\"empty\">No sensors discovered yet</div>';\n"
    "}\n"
    "function seg(l,sc){let h='<span class=\"bars\">';for(let i=0;i<5;i++)h+='<i class=\"sb '+(i<l\?sc:'')+'\" style=\"height:'+(6+i*3)+'px\"></i>';return h+'</span>';}\n"
    "function row(s){\n"
    "  const a=age(s.last), d=Date.now()/1000-s.last;\n"
    "  const st=s.last==null\?'miss':(d>900\?'crit':(d>300\?'warn':''));\n"
    "  const l=rssiLevel(s.rssi), sc=l>=4\?'good':(l===3\?'warn':(l===2\?'ser':'crit'));\n"
    "  const f=esc(s.fam), id=esc(s.id||'');\n"
    "  const en=s.en!==false;\n"
    "  return '<tr><td>'+f+'</td>'+\n"
    "    '<td class=\"mono\">'+id+'</td>'+\n"
    "    '<td class=\"mono rssi\">'+seg(l,sc)+'<span>'+s.rssi+'</span></td>'+\n"
    "    '<td class=\"mono'+(st\?' age-'+st:'')+'\">'+a+'</td>'+\n"
    "    '<td>'+(s.batt\?'<span class=\"tag warn\">LOW</span>':'<span class=\"tag ok\">OK</span>')+'</td>'+\n"
    "    '<td><input type=\"checkbox\"'+(en\?' checked':'')+' onchange=\"postEnable(\\''+f+'\\',\\''+id+'\\',this.checked)\"></td></tr>';\n"
    "}\n"
    "async function postEnable(fam,id,en){\n"
    "  const arr=S.roster||[];\n"
    "  const e=arr.find(x=>x.fam===fam&&x.id===id);\n"
    "  if(e)e.en=en;\n"
    "  renderRoster();\n"
    "  try{\n"
    "    await fetch(CONFIG_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sensors:[{fam:fam,id:id,en:en}]})});\n"
    "  }catch(e){}\n"
    "}\n"
    "function renderRoster(){\n"
    "  const rows=(S.roster||[]).slice();\n"
    "  rows.sort((a,b)=>{const x=a[sortKey],y=b[sortKey];let r;if(sortKey==='last'||sortKey==='rssi'||sortKey==='ch')r=(Number(x)||0)-(Number(y)||0);else r=String(x==null\?'':x).localeCompare(String(y==null\?'':y));return r*sortDir;});\n"
    "  $('rostBody').innerHTML=rows.map(row).join('')||'<tr><td colspan=\"6\" class=\"empty\">No sensors discovered</td></tr>';\n"
    "}\n"
    "function renderUpStat(){\n"
    "  const u=S.up, el=$('upStat');\n"
    "  if(!u||u.last==null){el.textContent='No upload recorded';el.className='stat';return;}\n"
    "  el.textContent=(u.ok\?'OK':'FAIL')+' \?\? '+age(u.last)+(u.ok\?'':' \?\? '+u.code);\n"
    "  el.className='stat '+(u.ok\?'good':'crit');\n"
    "}\n"
    "function renderUpload(){\n"
    "  const u=(S.cfg&&S.cfg.up)||{};\n"
    "  $('up_en').checked=!!u.en;$('up_cloud').checked=!!u.cloud;$('up_host').value=u.host||'';$('up_path').value=u.path||'';$('up_port').value=u.port||'';$('up_key').value=u.key||'';$('up_int').value=u.int||'';\n"
    "  renderServers();\n"
    "}\n"
    "const PROTO_NAMES={ecowitt:'Ecowitt',wunderground:'Wunderground',mqtt:'MQTT'};\n"
    "function srvRow(s){\n"
    "  const sel=Object.keys(PROTO_NAMES).map(k=>'<option value=\"'+k+'\"'+(s.proto===k\?' selected':'')+'>'+PROTO_NAMES[k]+'</option>').join('');\n"
    "  return '<div class=\"srv\">'+\n"
    "    '<select class=\"in mono sp\">'+sel+'</select>'+\n"
    "    '<input class=\"in sh\" placeholder=\"host\" value=\"'+esc(s.host||'')+'\" spellcheck=\"false\" autocomplete=\"off\">'+\n"
    "    '<input class=\"in mono sp2\" placeholder=\"port\" type=\"number\" value=\"'+esc(s.port||80)+'\">'+\n"
    "    '<input class=\"in sp3\" placeholder=\"path\" value=\"'+esc(s.path||'')+'\" spellcheck=\"false\" autocomplete=\"off\">'+\n"
    "    '<input class=\"in sk\" placeholder=\"key / station id\" value=\"'+esc(s.key||'')+'\" spellcheck=\"false\" autocomplete=\"off\">'+\n"
    "    '<label class=\"se\">on<input type=\"checkbox\"'+(s.en\?' checked':'')+'></label>'+\n"
    "    '<button class=\"btn sm sd\" type=\"button\">\?\?</button>'+\n"
    "    (s.code!=null\?'<span class=\"mono muted sc\">'+(s.code===200\?'ok':s.code)+'</span>':'')+\n"
    "    '</div>';\n"
    "}\n"
    "function renderServers(){\n"
    "  const a=(S.cfg&&S.cfg.servers)||[];\n"
    "  $('srvList').innerHTML=a.map(srvRow).join('');\n"
    "}\n"
    "function collectServers(){\n"
    "  return [...document.querySelectorAll('#srvList .srv')].map(r=>{\n"
    "    const sp=r.querySelector('.sp'),sh=r.querySelector('.sh'),sp2=r.querySelector('.sp2'),sp3=r.querySelector('.sp3'),sk=r.querySelector('.sk'),se=r.querySelector('.se input');\n"
    "    return {proto:sp.value,host:sh.value.trim(),port:parseInt(sp2.value,10)||80,path:sp3.value.trim(),key:sk.value.trim(),en:se.checked};\n"
    "  });\n"
    "}\n"
    "function buildFam(fe){\n"
    "  const cur={};document.querySelectorAll('#famTog input').forEach(i=>cur[i.value]=i.checked);\n"
    "  const set={};(S.roster||[]).forEach(x=>set[x.fam]=1);Object.keys(fe).forEach(k=>set[k]=1);\n"
    "  const fams=Object.keys(set).sort();\n"
    "  $('famTog').innerHTML=fams.map(f=>{const on=f in cur\?cur[f]:(fe[f]!==false);return '<label class=\"trow\"><span class=\"tl\">'+esc(f)+'</span><input class=\"tgl\" type=\"checkbox\" value=\"'+esc(f)+'\"'+(on\?' checked':'')+'></label>';}).join('')||'<div class=\"empty\">No families</div>';\n"
    "}\n"
    "function renderSystem(){\n"
    "  const c=S.cfg||{}, cal=c.cal||{};\n"
    "  const tz=$('tz');\n"
    "  TZ.forEach(t=>{const o=document.createElement('option');o.value=t;o.textContent=t;tz.appendChild(o);});\n"
    "  tz.value=c.tz||'UTC';\n"
    "  $('rf').value=String(c.rf||868);\n"
    "  $('cal_t_off').value=cal.t_off!=null\?cal.t_off:0;\n"
    "  $('cal_h_off').value=cal.h_off!=null\?cal.h_off:0;\n"
    "  $('cal_p_off').value=cal.p_off!=null\?cal.p_off:0;\n"
    "  $('cal_rain_g').value=cal.rain_g!=null\?cal.rain_g:1;\n"
    "  $('cal_wind_g').value=cal.wind_g!=null\?cal.wind_g:1;\n"
    "  $('cal_solar_g').value=cal.solar_g!=null\?cal.solar_g:1;\n"
    "  $('cal_uv_g').value=cal.uv_g!=null\?cal.uv_g:1;\n"
    "  buildFam(c.fam_en||{});\n"
    "}\n"
    "function renderDevInfo(){\n"
    "  const d=S.dev||{};\n"
    "  const it=[['MAC',d.mac],['IP',d.ip],['SSID',d.ssid],['WiFi RSSI',d.wifi_rssi!=null\?d.wifi_rssi+' dBm':null],['Free heap',fmtKB(d.heap)],['Uptime',fmtUpt(d.uptime)],['Firmware',d.fw]];\n"
    "  $('devInfo').innerHTML=it.map(x=>'<div class=\"di\"><span class=\"k\">'+x[0]+'</span><span class=\"v\">'+esc(x[1]==null\?'\?\?\?':x[1])+'</span></div>').join('');\n"
    "}\n"
    "function renderHeader(){\n"
    "  const d=S.dev||{};\n"
    "  $('name').textContent=d.name||'GW1100';\n"
    "  $('ipmac').textContent=(d.ip||'\?\?\?')+' \?\? '+(d.mac||'\?\?\?');\n"
    "}\n"
    "function renderUpd(){$('upd').textContent=lastFetchAt\?('updated '+age(Math.floor(lastFetchAt/1000))):'\?\?\?';}\n"
    "function updateDot(){\n"
    "  const dot=$('dot'),lab=$('dotLab');\n"
    "  if(demoMode){dot.className='dot warn';lab.textContent='DEMO';}\n"
    "  else if(!online){dot.className='dot crit';lab.textContent='OFFLINE';}\n"
    "  else{dot.className='dot good';lab.textContent='LIVE';}\n"
    "}\n"
    "function num(id){const v=parseFloat($(id).value);return isFinite(v)\?v:0;}\n"
    "function collectCfg(){\n"
    "  const up={en:$('up_en').checked,cloud:$('up_cloud').checked,host:$('up_host').value.trim(),path:$('up_path').value.trim(),port:parseInt($('up_port').value,10)||80,key:$('up_key').value,int:parseInt($('up_int').value,10)||60};\n"
    "  const cal={t_off:num('cal_t_off'),h_off:num('cal_h_off'),p_off:num('cal_p_off'),rain_g:num('cal_rain_g'),wind_g:num('cal_wind_g'),solar_g:num('cal_solar_g'),uv_g:num('cal_uv_g')};\n"
    "  const fam_en={};document.querySelectorAll('#famTog input').forEach(i=>fam_en[i.value]=i.checked);\n"
    "  return {up:up,tz:$('tz').value,rf:parseInt($('rf').value,10)||868,cal:cal,fam_en:fam_en,servers:collectServers()};\n"
    "}\n"
    "async function save(target){\n"
    "  const cfg=collectCfg(), old=S.cfg; S.cfg=cfg;\n"
    "  const st=$(target==='sys'\?'sysSaveStat':'upSaveStat');\n"
    "  st.textContent='saving\?\?\?';st.className='sstat';\n"
    "  try{\n"
    "    const r=await fetch(CONFIG_URL,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(cfg)});\n"
    "    const j=await r.json().catch(()=>({}));\n"
    "    if(!r.ok||j.ok===false)throw new Error(j.err||('HTTP '+r.status));\n"
    "    if(j.cfg)S.cfg=j.cfg;\n"
    "    st.textContent='saved';st.className='sstat good';\n"
    "  }catch(e){S.cfg=old;st.textContent=e.message||'failed';st.className='sstat crit';}\n"
    "}\n"
    "async function load(){\n"
    "  try{\n"
    "    const r=await fetch(STATE_URL,{cache:'no-store'});\n"
    "    if(!r.ok)throw 0;\n"
    "    S=await r.json();online=true;demoMode=false;lastFetchAt=Date.now();\n"
    "  }catch(e){\n"
    "    online=false;\n"
    "    if(!S){S=demo();demoMode=true;lastFetchAt=Date.now();}\n"
    "  }\n"
    "  renderHeader();updateDot();\n"
    "  if(!editing()){renderLive();renderRoster();}\n"
    "  renderUpStat();renderDevInfo();\n"
    "  if(!formsBuilt){renderUpload();renderSystem();formsBuilt=true;}\n"
    "  else buildFam((S.cfg&&S.cfg.fam_en)||{});\n"
    "}\n"
    "function tick(){\n"
    "  $('clock').textContent=new Date().toTimeString().slice(0,8);\n"
    "  if(!S)return;\n"
    "  renderUpd();renderUpStat();\n"
    "  if(curTab==='sensors' && !editing())renderRoster();\n"
    "}\n"
    "function show(tab){\n"
    "  curTab=tab;\n"
    "  document.querySelectorAll('.tab').forEach(b=>b.classList.toggle('on',b.dataset.tab===tab));\n"
    "  document.querySelectorAll('.sec').forEach(s=>s.classList.toggle('on',s.id===tab));\n"
    "  if(tab==='sensors')renderRoster();\n"
    "}\n"
    "function setSort(k){\n"
    "  if(sortKey===k)sortDir=-sortDir;\n"
    "  else{sortKey=k;sortDir=(k==='last'||k==='rssi')\?-1:1;}\n"
    "  document.querySelectorAll('.rost th[data-k]').forEach(th=>{th.classList.remove('sort-asc','sort-desc');if(th.dataset.k===sortKey)th.classList.add(sortDir>0\?'sort-asc':'sort-desc');});\n"
    "  renderRoster();\n"
    "}\n"
    "function demo(){const now=Math.floor(Date.now()/1000);return{\n"
    "  dev:{name:'GW1100-A1B2',mac:'BC:DD:C2:12:34:56',ip:'\?\?\?',ssid:'home-iot',wifi_rssi:-58,heap:31240,uptime:738400,fw:'2026.7.4',ts:now},\n"
    "  r:{t_in:21.4,h_in:47,p:1012.3,t_out:18.9,h_out:61,leaf_wet:0,wind_dir:225,wind_spd:2.4,wind_gust:4.1,rain:3.2,rain_rate:0,uv:0,solar:0,soil_moist:34,soil_t:16.8,soil_ec:0,pm25:4.1,pm10:5,co2:512,light_cnt:0,light_dist:0,leak:0},\n"
    "  roster:[{fam:'WS90',id:'4A3F12',ch:0,rssi:-71,last:now,batt:false},{fam:'WH31',id:'0B22C4',ch:1,rssi:-64,last:now-12,batt:false},{fam:'WH51',id:'2C08A1',ch:2,rssi:-78,last:now-45,batt:false},{fam:'WH41',id:'1F90EE',ch:1,rssi:-82,last:now-300,batt:true},{fam:'WH57',id:'3A11B7',ch:0,rssi:-69,last:now-8,batt:false}],\n"
    "  up:{ok:true,last:now-30,code:200},\n"
    "  cfg:{up:{en:true,host:'\?\?\?',path:'/data/report/',port:8080,key:'pass1234',int:60},tz:'UTC',rf:868,cal:{t_off:0,h_off:0,p_off:0,rain_g:1,wind_g:1,solar_g:1,uv_g:1},fam_en:{WS90:true,WH31:true,WH51:true,WH41:true,WH57:true,WH45:true,WH55:true}}\n"
    "};}\n"
    "function init(){\n"
    "  document.querySelectorAll('.tab').forEach(b=>b.addEventListener('click',()=>show(b.dataset.tab)));\n"
    "  document.querySelectorAll('.rost th[data-k]').forEach(th=>th.addEventListener('click',()=>setSort(th.dataset.k)));\n"
    "  $('upSave').addEventListener('click',()=>save('up'));\n"
    "  $('sysSave').addEventListener('click',()=>save('sys'));\n"
    "  $('upReveal').addEventListener('click',e=>{e.preventDefault();const i=$('up_key'),s=i.type==='password';i.type=s\?'text':'password';$('upReveal').textContent=s\?'hide':'show';});\n"
    "  $('srvAdd').addEventListener('click',()=>{const d=document.createElement('div');d.innerHTML=srvRow({proto:'wunderground',host:'',port:80,path:'',key:'',en:false});$('srvList').appendChild(d.firstChild);});\n"
    "  $('srvList').addEventListener('click',e=>{if(e.target.classList.contains('sd'))e.target.closest('.srv').remove();});\n"
    "  document.querySelector('.rost th[data-k=\"last\"]').classList.add('sort-desc');\n"
    "  tick();load();setInterval(load,POLL);setInterval(tick,1000);\n"
    "}\n"
    "document.addEventListener('DOMContentLoaded',init);\n"
    "</script>\n"
    "</body>\n"
    "</html>\n"
    "\n"
    ;
